const item = $input.first().json;
const headers = item.headers ?? {};
const provided = String(headers['x-n8n-secret'] ?? headers['X-N8N-Secret'] ?? '');
const expected = String($env.N8N_WEBHOOK_SECRET ?? '');
if (!expected) throw new Error('N8N_WEBHOOK_SECRET is not configured in n8n');
if (provided.length !== expected.length) throw new Error('Unauthorized: bad webhook secret');
let diff = 0;
for (let i = 0; i < expected.length; i++) diff |= provided.charCodeAt(i) ^ expected.charCodeAt(i);
if (diff !== 0) throw new Error('Unauthorized: bad webhook secret');
const body = item.body ?? item;
const rawUrl = String(body.productUrl ?? '').trim();
if (!rawUrl) throw new Error('productUrl is required');
let u;
try { u = new URL(rawUrl); } catch { throw new Error('productUrl must be a valid URL'); }
if (!['http:', 'https:'].includes(u.protocol)) throw new Error('productUrl must be http(s)');
const host = u.hostname.toLowerCase();
const blocked = host === 'localhost' || host.endsWith('.localhost') || host === '127.0.0.1' || host === '0.0.0.0' || host === '[::1]' || host.startsWith('10.') || host.startsWith('192.168.') || /^172\.(1[6-9]|2\d|3[01])\./.test(host);
if (blocked) throw new Error('productUrl host is not allowed');
const durationSeconds = Math.min(180, Math.max(15, Number(body.durationSeconds ?? 15) || 15));
const language = ['hinglish', 'hindi', 'english'].includes(body.language) ? body.language : 'hinglish';
const payload = {
  productUrl: u.toString(),
  durationSeconds,
  language,
  voice: body.voice ?? 'hi-IN-SwaraNeural',
  visualStyle: body.visualStyle ?? 'premium_dark'
};
if (body.platform) payload.platform = body.platform;
if (body.idempotencyKey) payload.idempotencyKey = String(body.idempotencyKey);
return [{ json: payload }];

const res = $input.first().json;
const prev = $('init-poll').first().json;
const job = res.data ?? {};
return [{ json: { jobId: prev.jobId, attempts: prev.attempts + 1, status: job.status ?? 'UNKNOWN', job } }];

const j = $input.first().json;
const base = String($env.BACKEND_URL ?? '').replace(/\/$/, '');
const stages = Array.isArray(j.job && j.job.stages) ? j.job.stages.map(s => ({ key: s.stageKey ?? s.key, status: s.status })) : [];
return [{ json: { ok: true, jobId: j.jobId, status: j.status, downloadUrl: base + '/api/v1/jobs/' + j.jobId + '/download', resultUrl: base + '/api/v1/jobs/' + j.jobId + '/result', stages } }];

const j = $input.first().json;
const base = String($env.BACKEND_URL ?? '').replace(/\/$/, '');
return [{ json: { ok: true, jobId: j.jobId, status: 'WAITING_FOR_REVIEW', message: 'Job needs human review before delivery. Open the dashboard to approve or reject.', dashboardUrl: base + '/jobs/' + j.jobId } }];
